    if k > n * n:
        return -1

    matrix = [[0] * n for _ in range(n)]

    # Place half of the ones on the upper triangle including the diagonal
    ones_to_place = k // 2 + (k % 2)
    row = 0
    col = 0
    while ones_to_place > 0:
        if row == col or col < row:
            matrix[row][col] = 1
            ones_to_place -= 1
        col += 1
        if col == n:
            col = 0
            row += 1

    # Place the remaining ones on the lower triangle
    for i in range(1, n):
        for j in range(i):
            if ones_to_place > 0:
                matrix[i][j] = 1
                ones_to_place -= 1

    return matrix

